(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[939],{3984:t=>{t.exports={phrase:"TextReveal_phrase__D9WYT",reveal:"TextReveal_reveal__pg9AW","focus-phrase":"TextReveal_focus-phrase__IHNxd"}},6291:(t,e,s)=>{"use strict";s.d(e,{TextReveal:()=>d});var a=s(7782),n=s(8720),o=s(8648),r=s(8806),i=s(3984),c=s.n(i);function d(t){var e;let{text:s,phrases:i}=t,d=(0,r.useRef)(null),h=(0,n.W)(d,{once:!0,amount:.3}),u=(0,o.I)(),l=null!=i?i:null!=(e=s.match(/[^，。！？、；： ]*[，。！？、；： ]+|[^，。！？、；： ]+/gu))?e:[s];return(0,a.jsx)("span",{ref:d,className:c().reveal,"data-text-reveal":h&&!u?"running":void 0,children:l.map((t,e)=>(0,a.jsx)("span",{className:c().phrase,style:{"--reveal-delay":"".concat(66*Math.min(e,8),"ms")},children:t},e))})}},7849:(t,e,s)=>{"use strict";function a(t,e){return"/media/portfolio/".concat(t).concat(e).concat("garment-steamer"===t?"?v=final-20261126":"")}s.d(e,{t2:()=>r,mk:()=>o,EM:()=>a,Te:()=>n});let n=[{id:"poseidon",title:"Poseidon 救生衣宣传片",category:"水上运动 \xb7 产品广告",description:"从沙洲穿戴出发，串起海钓、桨板、水上摩托与皮划艇，最终回到五色陈列。",durationSeconds:23.568,aspect:[16,9],premise:"先让观众看清救生衣怎么穿、细节长什么样，再用不同水上运动交代上身效果，最后把场景中的配色收回一张产品阵列。",beats:[{start:0,end:2.267,action:"从海面飞向沙洲",shot:"超广角俯瞰绕过弧形浅滩，白色字标掠过沙面。镜头逼近岸边人物和装备，交代故事从下水前开始。"},{start:2.267,end:4.667,action:"穿上橙色救生衣",shot:"正面胸腰中近景，双手抬起衣身套上双肩，再沿前襟向腰间移动；海岸仍在人物背后。"},{start:4.667,end:6.667,action:"看清肩部、口袋和腰扣",shot:"依次切到肩带的挂环、橙色口袋和腰带卡扣。黑色五金和织带对比橙色面料，扣件收在画面中心。"},{start:6.667,end:10.033,action:"跟随海钓抛竿",shot:"先用鱼竿斜线和海面接出场景，再切到穿深色救生衣的钓手。从收线姿态切向抬竿、挥出，动作顶点对着明亮天空。"},{start:10.033,end:12.8,action:"把桨板水花带到镜头前",shot:"从板头低机位看向划手，再切向顺着白色板头看海的视角。桨叶划入画边，水花遮住大半画面。"},{start:12.8,end:15.1,action:"从水花转入水上摩托",shot:"低视角保持海天线，亮绿色装备随摩托驶过。白色浪迹逐渐扩大并盖住画面，接向空中段。"},{start:15.1,end:18.067,action:"由高空切回蓝色救生衣",shot:"先从倾斜的海平线看伞翼，再切到海面前的上身近景，蓝色衣身和外侧黑色织带成为焦点。"},{start:18.067,end:19.333,action:"在划桨动作中切换配色",shot:"从皮划艇舱口上缘取胸腰特写，以相近的划桨位置切换橙、黑、紫色款。"},{start:19.333,end:23.568,action:"以五色陈列和片尾字标收束",shot:"黑底先出现单件，再排开五件。中间款保持清晰，两侧退焦，最后叠出片尾白色字标 Poesidon。"}],decisions:[{question:"为什么先拍穿戴，再切到海上？",answer:"穿戴段给肩部、口袋和腰扣单独留时间。进入水上场景后，观众已经认得衣身和扣带，可以把注意力转到人与场景的关系。"},{question:"不同运动之间靠什么衔接？",answer:"桨板水花先填满近处，再由水上摩托的白浪接住亮度和运动。一段从慢到快，画面一直留着海面的空间参照。"},{question:"为什么划桨段与黑底陈列都出现配色？",answer:"划桨特写保持取景位置相近，便于比较上身的颜色。黑底把五件放进同一构图，给观众看完整阵列的时间。"}],alternate:"可以把橙色腰扣的扣合放到首秒，借扣合声硬切水上动作。中段用同机位依次切换配色，末段保留黑底五色陈列，做一版面向商品页的短片。"},{id:"garment-steamer",title:"LAFAVRI 手持吸烫机",category:"家电 \xb7 功能演示",description:"从出门前的皱衬衫切入，演示转头、挂烫与平烫、补水和行李箱收纳。",durationSeconds:41.355,aspect:[16,9],premise:"以皱衬衫建立具体需求，随后交替给出工作面的产品特写和实际使用动作。最后让蓝衬衫回到人物身上，从家中使用接到出行收纳。",beats:[{start:0,end:6.4,action:"挂着的皱衬衫引出旋转机头",shot:"暖色室内以皱衬衫占左、白机身占右。手扶工作面转动，连续展示孔面、机头侧面和背部黑色屏幕。"},{start:6.4,end:8.63,action:"把电机和吸烫动作做成示意",shot:"从工作面推近至透明机身，蓝色线条穿过电机，再切到气流图形和深色衣料。画面将内部结构与布料受力放在相邻两镜。"},{start:8.63,end:10.967,action:"用双画幅比较挂烫过程",shot:"正面并列两件灰衬衫，黑色设备和白色吸烫机分别从画边进入。机头沿衣身往下移，退场后保留衬衫画面。"},{start:10.967,end:14.733,action:"从挂着的衬衫切到桌面平烫",shot:"侧前方斜俯看浅色上衣与垫板，一只手握机器移动，另一只手稳住衣料。抬起机头后，手掌掠过工作区域。"},{start:14.733,end:18.9,action:"给工作面和蒸汽单独留特写",shot:"工作面孔阵先占画面中心，随后用分离式机头构造示意过渡到浅色织物，白色蒸汽落在表面。"},{start:18.9,end:24.033,action:"取下水箱、补水并回装",shot:"侧近景下透明水箱置于水龙头下。镜头随后跟到台面，让手持机身回到水箱上方，再展示两者重新对接。"},{start:24.033,end:31.533,action:"由面料切换带出屏幕与档位",shot:"固定相近的手握角度，在灰、奶白、棕色衣料之间切换。接着推近亮起的黑色屏幕，再回到工作面。"},{start:31.533,end:37.6,action:"穿衣照镜后收进行李箱",shot:"先拍穿蓝衬衫的女性与同框镜中反射，再从斜上方拍敞开的箱内。人物把机器和收好的线放在衣物旁。"},{start:37.6,end:41.355,action:"以家居陈列和品牌字标结束",shot:"圆桌上一侧是叠好的浅色衣物，另一侧是站立的白色吸烫机。产品名称出现后切到 LAFAVRI 白底尾卡。"}],decisions:[{question:"怎么让吸烫原理和使用动作都看得明白？",answer:"电机剖面和气流图形给出原理示意。紧接着把工作面对准灰衬衫，后续的平烫段还留着扶衣料的手，让观众看清接触和移动。"},{question:"为什么从补水直接接回衣料？",answer:"先让透明水箱离开机身，镜头看见进水和回装，再交回使用动作。一段日常维护也具有完整起点和终点。"},{question:"出行感来自哪几个镜头？",answer:"开场字幕提出出门前皱衣的困扰。片尾以穿上蓝衬衫、照镜、收纳机器连续回应，让功能示意回到人的日常动作。"}],alternate:"可以从人物准备出门的动作开场，用一次同机位、同光线的局部平烫作为主镜头。随后只用两个短特写解释机头转向和水箱回装，再回到照镜与收纳。"},{id:"asw33-23",title:"AirMars 智能手表系列",category:"消费电子 \xb7 场景广告",description:"从橙色地貌和双表亮相开始，穿过山地运动、雨天通勤、办公与睡眠场景。",durationSeconds:47.879,aspect:[16,9],premise:"用荒漠与双表建立运动调性，再把界面、骑行路线、工作来电和夜间图表放进不同生活场景。片尾回到产品陈列和 AirMars 标识。",beats:[{start:0,end:4.467,action:"从橙色荒漠进入腕表界面",shot:"地平线和岩石先占满画面，两枚表在空中亮相。径向模糊把广景带到浅底表盘特写，彩色应用图标变成焦点。"},{start:4.467,end:8.733,action:"由弯道骑行落到腕上数据",shot:"后方高机位跟着骑行者转入山路，画中叠加路线图。随后切到日光下手腕近景，把地形、路线和屏幕信息接起来。"},{start:8.733,end:10.867,action:"把电池画面变成表内示意",shot:"黑底斜视表壳，透明外壳露出内部，绿色电池示意和屏幕充电环并置。主体放大后切回真实环境的动作场景。"},{start:10.867,end:21.633,action:"用不同动作连续展示运动场景",shot:"骑行者低头看表后，连续接跑道、室内羽毛球、瑜伽侧伸和山顶徒步。运动图标与字幕保持构图上的辨识度。"},{start:21.633,end:28.067,action:"让水花串起冲浪与雨天",shot:"橙底产品镜头用近处水花围住表壳，随后切到外景浪花里的冲浪者，再切到雨伞下的腕表近景。"},{start:28.067,end:36.7,action:"从表盘操作接到通勤与办公",shot:"先给出手指接近应用界面的近景，再用快速模糊转入地铁中低头看表的人。办公中景接近景，手指轻触来电界面。"},{start:36.7,end:41,action:"从卧室动作转到睡眠画面",shot:"冷蓝色卧室先拍人物伸展，再叠化到腕表特写。紫色月亮表盘和旁边的柱形图提供夜间信息。"},{start:41,end:47.879,action:"以系列陈列和品牌标识收束",shot:"回到橙底多表盘阵列，随后在岩石上并置圆表与方表。最后用短促故障纹理转入黑底 AirMars 标识。"}],decisions:[{question:"怎么把骑行数据与场景接上？",answer:"先让后方高机位交代真实道路的弯曲形状，再叠出路线图，紧接着回到腕上屏幕。观众可以顺着弯道理解数据的来由。"},{question:"动作很多，观众如何知道还在讲什么？",answer:"骑行、跑步、羽毛球和瑜伽更新动作和场景，屏幕上的运动标识和同组文案持续出现。信息连续，画面可以快速切换。"},{question:"为什么办公段补了手指触表的近景？",answer:"中景让观众看到手表与办公动作在一起，近景交代手指接触的位置和来电界面。功能通过一件可追踪的动作结束。"}],alternate:"可以把山地骑行设为一条单独短片。开场先给弯道和路线图，中段只保留腕上屏幕与骑行者的动作，最后在同一条山路完成腕表定帧。"},{id:"f09",title:"AirMars F09 智能蓝牙 FM 眼镜",category:"智能眼镜 \xb7 城市通勤",description:"从窗边戴上眼镜，到街头骑行、触碰镜腿和来电提示，把功能放进一次完整的出行。",durationSeconds:30.1,aspect:[16,9],premise:"用桌上的眼镜、手机和钥匙交代出门前的状态，再用一个骑行者串起使用场景。随着景别从街道全景切到镜腿和镜片特写，叙事从城市环境回到产品细节，最后回到开场的桌面。",beats:[{start:0,end:1.93,action:"桌面亮相与取用",shot:"暖色窗光从侧面打亮黑色镜框，手机与钥匙作陪衬。手伸向镜腿，带出下一镜的佩戴。"},{start:1.93,end:4.5,action:"窗边戴上眼镜",shot:"侧面近景保持人物、窗框和远处楼群的位置，双手把眼镜贴到脸上，再用指尖接触镜腿。"},{start:4.5,end:9.1,action:"跟着骑行者出门",shot:"先给眼镜和人物表情，再拉开到带车把的侧前方中景，移动中的玻璃楼立面交代速度和方向。"},{start:9.1,end:12.67,action:"放大镜腿触控",shot:"侧脸特写以指尖和镜腿接触为中心，旁侧叠加透明的音乐与 FM 界面示意。"},{start:12.67,end:19.67,action:"穿过城市街口",shot:"街口全景先交代车流和斑马线，后方及侧面的视角接着跟随骑行者穿过路口。"},{start:19.67,end:22.23,action:"呈现来电提示",shot:"回到骑行者的胸部以上近景，在头部旁的留白处叠加 Alex 来电和接听图标，让人物动作和提示同时可见。"},{start:22.23,end:26.5,action:"逆光中展示镜片变化",shot:"太阳落在侧脸后方，近景看镜片从浅变深，接着切到脱离人物的眼镜特写，强调镜片颜色。"},{start:26.5,end:30.1,action:"回到桌面与品牌落版",shot:"先展示眼镜侧面和轮廓，再回到暖光桌面及型号字样，以黑底 AirMars 默笙标志收尾。"}],decisions:[{question:"为什么在触控特写之间保留街口全景？",answer:"车流、建筑和斑马线表明人物从室内进入了具体的通勤场景。随后再看手指和来电图示，观众有足够的空间信息理解这些镜头发生在哪里。"},{question:"画面怎么交代镜片颜色变化？",answer:"把光源置于人物背后，使逆光环境和镜片变化出现在同一段近景中。切到独立产品后，镜框轮廓和深色镜片仍能看清。"},{question:"透明界面叠加承担什么作用？",answer:"镜腿触碰本身很短，旁侧的界面把不同动作对应的音乐、FM 和来电提示可视化，也留出了人物眼睛和手指的位置。"}],alternate:"通勤版可从车把旁的镜腿触控开场，接一个街口远景交代行进方向，再用停车后的近景演示接听。把逆光变色留作最后一个功能镜头，以同一幅桌面产品画面收束。"},{id:"kids-life-jacket",title:"儿童款救生衣",category:"儿童产品 \xb7 水上活动",description:"从池边入水到栈道穿戴，跟着孩子看水面漂浮、海上划桨和浅滩玩球。",durationSeconds:26.912,aspect:[16,9],premise:"用一记入水开场，再回到岸上看清救生衣怎么穿。中段让水面漂浮和划桨放慢节奏，最后以孩子追着球跑向镜头的水花呼应开头。",beats:[{start:0,end:1.8,action:"从池边跃入水面",shot:"低机位同时保留池边和水面，穿橙色救生衣的孩子向水里跃出。"},{start:1.8,end:4,action:"让水花带出片头",shot:"画面进入水下，气泡经过镜头，白色字标在蓝色水中出现。"},{start:4,end:8.6,action:"近看栈道上的穿戴",shot:"用一组上身近景分别看胸前拉链、肩带和腰侧织带，成人的手随动作进入画面。"},{start:8.6,end:12.433,action:"从栈道走到浅滩",shot:"拉开距离看到孩子与身旁的板具，再切到穿蓝色和粉色救生衣的孩子走进浅水。"},{start:12.433,end:14.1,action:"看两人在水面漂浮",shot:"镜头贴近水面，两名孩子仰躺在清水里，救生衣的颜色随着波光显现。"},{start:14.1,end:16.467,action:"在逆光里切到划桨",shot:"用海面远景保留天空与水线，板上的人物划桨经过斜照的日光。"},{start:16.467,end:18.9,action:"从板头拍孩子的反应",shot:"镜头移到板头附近。孩子笑着伸手，近处水花溅入前景。"},{start:18.9,end:24.2,action:"跟拍浅滩上的玩球动作",shot:"贴近水面拍孩子跑动时的水花与弹起的彩球，再拉开到能同时看见多种救生衣颜色的画面。"},{start:24.2,end:26.912,action:"用多人画面与字标收尾",shot:"宽景留住跑向镜头的人群，画面渐暗，白色字标出现在中央。"}],decisions:[{question:"为什么先入水，再回到栈道看穿戴？",answer:"跃入水面用一个清楚的动作交代水上主题，栈道近景随后让观众看清拉链和织带的位置。再次切回水里时，观众已经认得穿在孩子身上的产品。"},{question:"漂浮和划桨为什么需要不同的景别？",answer:"贴近水面能看清孩子漂浮时的姿态和救生衣颜色，海上远景则交代划桨人物、板具和周围的空间。之后切到孩子的笑脸，让运动方向和人物反应接在一起。"},{question:"浅滩玩球怎样收束全片？",answer:"彩球把视线带过一组奔跑的人物，多种颜色在同一场景里自然出现。脚边水花呼应池边入水，最后再让字标有独立的停留时间。"}],alternate:"穿戴优先的短版可以从栈道拉链近景开场，接一个中景看清整件救生衣，再用入水和划桨各带一次场景变化。片尾选浅滩上几种颜色同框的宽景，保留原片字标。"},{id:"abo21",title:"AirMars ABO21 开放式耳机",category:"开放式耳机 \xb7 运动与通勤",description:"用佩戴、跑步和划船的使用镜头，串起耳挂结构、充电盒、声波与芯片的演示。",durationSeconds:47.63,aspect:[16,9],premise:"用健身房佩戴建立产品用途，随后交替使用人体动作和深蓝产品镜头。外观、运动、随身充电与声学示意各有独立段落，结尾回到开盒主视觉。",beats:[{start:0,end:2.37,action:"先认充电盒",shot:"蓝色型号画面后切到充电盒正面与开合缝微距，亮起的指示灯和表面反光建立材质印象。"},{start:2.37,end:7,action:"从耳挂轮廓过渡到真人佩戴",shot:"背光微距中由手指捏住耳机，再切到健身房侧面近景，手把开放式耳挂戴到耳边。"},{start:7,end:11.67,action:"交代贴耳形态与跑步使用",shot:"深蓝棚拍展示耳机转面和耳挂轮廓，切到跑步机上的人物侧面，让耳机回到运动中的真实比例。"},{start:11.67,end:16.2,action:"切换到水滴与器械运动",shot:"开盒画面引向单只耳机的水滴近景，再用低机位广角展示人物做划船动作。"},{start:16.2,end:22.9,action:"把听感做成视觉节奏",shot:"把耳机放进横贯画面的声波，接到扬声器振动示意，再用人物与大字环绕的画面收束。"},{start:22.9,end:32.1,action:"展示充电与续航文字",shot:"从充电盒切到 Type-C 插头连接特写，再展示开盖耳机和发亮的计时图形，字幕给出片中标示的时间。"},{start:32.1,end:35.1,action:"补充城市使用情境",shot:"在户外用斜侧后方中景同时容纳人物的耳机、手持手机和街道背景，从训练场景过渡到日常使用。"},{start:35.1,end:42.77,action:"从内部示意回到表面触控",shot:"发声部件的分解动效接到电路板与芯片，随后切回外壳和孔位细节，最后给出接触外壳的手指特写。"},{start:42.77,end:47.63,action:"开盒与品牌收尾",shot:"蓝色侧光勾出开盒状态和耳挂弧线，回到带标题的组合画面，最后用黑底 AirMars 标志结束。"}],decisions:[{question:"为什么耳挂特写后马上接佩戴？",answer:"手拿时能看清轮廓，戴到耳边后能看出挂耳位置和产品尺度。两个连续画面把外形和使用方式连起来。"},{question:"深蓝技术镜头和真人运动镜头怎样衔接？",answer:"先让真人动作交代佩戴或运动，接着用水滴、波形和部件动画集中呈现单项信息。每次换到棚拍后，耳机仍是画面中心。"},{question:"充电段如何让接口与续航图形各司其职？",answer:"连接特写交代线材进入盒体的位置，开盒画面明确配套关系，最后用计时图形承接片中文字。三层信息依次出现，避免塞在同一画面里。"}],alternate:"可另做二十秒运动版，从人物戴上耳机和跑步起势开场，把贴耳轮廓、水滴和收回充电盒压成三段。芯片、分解与长续航内容留给详情页长版，短版结尾继续使用现有开盒构图。"},{id:"abh01",title:"AirMars ABH01 头戴式耳机",category:"头戴式耳机 \xb7 城市旅行",description:"以夜街与酒店入口串起出行情境，在黑金和奶油色变化中展示耳罩、连接与折叠细节。",durationSeconds:19.3,aspect:[16,9],premise:"先用夜街的高反差环境勾出耳机轮廓，再把低调黑金棚拍留给触感与技术信息。浅色耳垫之后转到行李箱和人物佩戴，最后把出行画面收进主视觉。",beats:[{start:0,end:2.8,action:"从人物海报切进夜街",shot:"短暂出现 PURE LISTENING 构图，切到耳机在近景、雨后街道在远处的低调画面，车灯散景和湿地反光保留空间纵深。"},{start:2.8,end:5.2,action:"展示黑色耳罩细部",shot:"近距离保留耳罩外壳纹理、转轴和金色标志，侧光只提亮关键边缘。"},{start:5.2,end:7.57,action:"让续航信息进入产品构图",shot:"黑色耳机置于金色光圈前，数值动效在耳机旁变化，字幕同步提示片中标示的续航。"},{start:7.57,end:9.93,action:"从外壳转入连接示意",shot:"耳罩内叠现金色电路和标注 6.0 的芯片图形，沿用黑金配色使技术镜头保持连贯。"},{start:9.93,end:12.3,action:"浅色耳垫质感特写",shot:"画面转为暖白侧光，贴近耳垫与缝线，以滚动的小金球和材质起伏吸引视线。"},{start:12.3,end:13.77,action:"用行李参照表现折叠",shot:"耳机和行李箱拉杆同框，固定视角观察耳罩从展开到收拢，让动作与旅行场景建立联系。"},{start:13.77,end:15.13,action:"人物带着行李出现",shot:"酒店入口以斜向暖光给出场景方向，人物在行李箱旁抬手佩戴耳机，空间仍保持完整。"},{start:15.13,end:19.3,action:"回到佩戴主视觉",shot:"带耳机的侧脸和 PURE LISTENING 大字形成结束构图，停留后切至黑底 AirMars 默笙标志。"}],decisions:[{question:"为什么用黑金表现技术，再让耳垫镜头转为浅色？",answer:"深底便于区分耳罩外壳和发光图形，浅色侧光更适合看缝线、耳垫厚度和受光起伏。转色同时提示观众从规格阅读切换到触感。"},{question:"行李箱在折叠镜头里做了什么？",answer:"拉杆提供固定的垂直尺度，耳罩收拢的幅度一眼可见。行李在随后的酒店镜头中继续出现，也把结构演示接回出行。"},{question:"为什么保留两种落版画面？",answer:"人物与大字让佩戴轮廓成为最后一个故事画面。随后单独显示品牌标志，留出了清晰的品牌识别时间。"}],alternate:"可做旅行叙事版，从酒店门口的人物和行李先建立目的地，用放下行李、取出耳机、戴上的顺序串联动作。将夜街放到佩戴之后，并在其中穿插耳罩与转轴两处细节，保留原版黑金质感。"},{id:"handwarmer",title:"Karecel 暖手宝冬季广告",category:"生活电器 \xb7 产品广告",description:"为冬季出行与节日送礼制作的双机暖手宝短片。",durationSeconds:31.068,aspect:[16,9],premise:"在人物使用产品的动作中交代随身收纳和充电，给接口与连接过程单独留出画面。",beats:[{start:0,end:3.333,action:"雪场分享一对暖手宝",shot:"雪山背景中，两人面对面。中近景把注意力落到手里的产品和递接动作上。"},{start:3.333,end:9.933,action:"滑过雪道，切到暖感示意",shot:"低机位跟着滑雪板与雪花，随后切到浅色背景上的两只暖手宝，以暖色图形表现发热区域。"},{start:9.933,end:15.5,action:"演示随身拿取与收纳",shot:"用人物腰侧和手部特写展示拿取与收纳，让衣物提供大小参照。"},{start:15.5,end:19.55,action:"桌面展示双机充电",shot:"斜上方看向木桌。两只暖手宝、充电线与电源同框，手伸入画面完成连接。"},{start:19.55,end:21.616,action:"在火炉边暖手",shot:"以火光作近景，两人在雪屋外并坐，手部动作接回片头的分享。"},{start:21.616,end:27.5,action:"把暖手宝放进节日袜",shot:"从手持产品的近景接到红色礼物袜，再拉开画面露出圣诞树与室内暖光。"},{start:27.5,end:31.068,action:"配色陈列与品牌收尾",shot:"不同配色落在壁炉和圣诞树前的同一构图中，最后切入 Karecel 品牌字标。"}],decisions:[{question:"为什么从递给另一个人开始？",answer:"递接动作先交代这是一对可分开使用的暖手宝，也为火炉边的双人场景和片尾送礼留下呼应。"},{question:"为什么给充电单独一个固定镜头？",answer:"两只产品和电源同框，观众能顺着线看清连接关系。"}],alternate:"商品页可用雪场交接开场，紧接桌面充电，最后以多色陈列收尾。"}].map(t=>({...t,src:a(t.id,".mp4"),poster:a(t.id,".webp")}));function o(t){return[t.beats[0],t.beats[Math.floor((t.beats.length-1)/2)],t.beats.at(-1)].map((e,s)=>({...e,image:a(t.id,"-frame-".concat(s+1,".webp")),time:(e.start+e.end)/2}))}function r(t){let e=Math.floor(t/60),s=(t%60).toFixed(1).padStart(4,"0");return"".concat(String(e).padStart(2,"0"),":").concat(s)}}}]);